u_{\theta}(y) = \mathcal{A}_L \circ\sigma \circ \mathcal{A}_{L-1}\ldots \ldots \ldots \circ\sigma \circ \mathcal{A}_2 \circ \sigma \circ \mathcal{A}_1(y).

\label{ass:nn}
Let $q\in\{2,\infty\}$. For any $B,\varepsilon>0$, $\ell \in\mathbb{N}$, $t\in [0,T]$ and any $v\in \mathcal{X}$ with $\norm{v}_{C^\ell}\leq B$ there exist a neural network $\mathcal{U}^\varepsilon(v,t):D\to\mathbb{R}$ and a constant $C_{\varepsilon,\ell}^B>0$ s.t.
\begin{equation}
    \norm{\mathcal{U}^\varepsilon(v,t)-\mathcal{G}(v)(\cdot,t)}_{L^q(D)} \leq \varepsilon \quad \text{and} \quad \max_{t\in [0,T]} \norm{\mathcal{U}^\varepsilon(v,t)}_{W^{\ell,q}(D)} \leq C_{\varepsilon,\ell}^B.
\end{equation}

\label{ass:diff-operator}
Let $k,\ell\in\mathbb{N}$,  $q\in\{2,\infty\}$, $C>0$ be independent from $d$. For all $v\in\mathcal{X}$ it holds,
\begin{equation}
    \norm{\mathcal{L}(\mathcal{G}_\theta(v))}_{L^q([0,T]\times D)} \leq C \cdot \mathrm{poly}(d)\cdot 

    \sum_{\substack{(k',{\bm{\alpha}})\in\mathbb{N}^{d+1}_0\\ k'\leq k, \norm{{\bm{\alpha}}}_1\leq \ell }} \norm{D^{(k',{\bm{\alpha}})}(\mathcal{G}-\mathcal{G}_\theta)}_{L^q([0,T]\times D)}. 
\end{equation}

\label{thm:nn-to-pinn}
Let $s,r\in\mathbb{N}$, let $u\in C^{(s,r)}([0,T]\times D)$ be the solution of the PDE \eqref{eq:PDE} and let Assumption \ref{ass:nn} be satisfied. There exists a constant $C(s,r)>0$ such that for every $M\in\mathbb{N}$ and $\varepsilon, h>0$ there exists a tanh neural network $u_\theta:[0,T]\times D\to \mathbb{R}$ for which it holds that,
\begin{equation}
\label{eq:pinnerr1}
    \norm{u_\theta-u}_{L^q([0,T]\times D)} \leq C(\norm{u}_{C^{(s,0)}}M^{-s}+\varepsilon). 
\end{equation}
and if additionally Assumption \ref{ass:partition} and Assumption \ref{ass:diff-operator} hold then,
\begin{equation}\label{eq:pinn-acc}
\begin{split}
     &\norm{\mathcal{L}(u_\theta)}_{L^2([0,T]\times D)} + \norm{u_\theta-u}_{L^2(\partial([0,T]\times D))} \\
     &\qquad \leq C\cdot \mathrm{poly}(d)\cdot \ln^k(M)(\norm{u}_{C^{(s,\ell)}}M^{k-s}+M^{2k}(\varepsilon h^{-\ell}+C^B_{\varepsilon,\ell}h^{r-\ell})). 
\end{split}
\end{equation}
Moreover, $\mathrm{depth}(u_\theta)\leq C\cdot\mathrm{depth}(\mathcal{U}^\varepsilon)$ and $\mathrm{width}(u_\theta) \leq CM\cdot \mathrm{width}(\mathcal{U}^\varepsilon)$.

\label{ass:stability}
Assumption \ref{ass:nn} is satisfied and let $p\in\{2,\infty\}$. For every $\varepsilon>0$ there exists a constant $C^\varepsilon_{\mathrm{stab}}>0$ such that for all $v,v'\in \mathcal{X}$ it holds that,
\begin{equation}
    \norm{\mathcal{U}^\varepsilon(v,T)-\mathcal{U}^\varepsilon(v',T)}_{L^2}\leq C^\varepsilon_{\mathrm{stab}} \norm{v-v'}_{L^p}. 
\end{equation}

\label{thm:nn-to-fno}
Let $r\in\mathbb{N}$, $T>0$, let $\mathcal{G}: C^r(\mathbb{T}^d)\to C^r(\mathbb{T}^d)$ be an operator that maps a function $u_0$ to the solution $u(\cdot, T)$ of the PDE \eqref{eq:PDE} with initial condition $u_0$, let Assumption \ref{ass:stability} be satisfied {\color{black}and let $p^*\in\{2,\infty\}\setminus\{p\}$}. Then there exists a constant $C>0$ such that for every $\varepsilon>0$, $N\in\mathbb{N}$ there is an FNO $\mathcal{G}_\theta: L^2_N(\mathbb{T}^d)\to L^2_N(\mathbb{T}^d)$ of depth $\mathcal{O}(\mathrm{depth}(\mathcal{U}^\varepsilon))$ and width $\mathcal{O}(N^d\mathrm{width}(\mathcal{U}^\varepsilon))$ with accuracy, 
\begin{equation}\label{eq:nn-to-fno}
    \norm{\mathcal{G}-\mathcal{G}_\theta}_{L^2}
\leq C(\varepsilon + C^\varepsilon_{\mathrm{stab}}BN^{-r+d/p^*}+ C_{\varepsilon,r}^{CB}N^{-r}).
\end{equation}

\label{thm:deeponet-to-pido}
Consider an operator $\mathcal{G}:\mathcal{X}\to C^r(D)$, $r\in\mathbb{N}$, that satisfies Assumption \ref{ass:partition} and Assumption \ref{ass:diff-operator} with $\ell\in N$. Let $\lambda^*\in (0,\infty]$, let $\lambda, C(\lambda)>0$ with $\lambda\leq\lambda^*$ and let $\sigma:\mathbb{N}\to\mathbb{R}$ be a function such that for all $p\in \mathbb{N}$ there is a DeepONet/FNO $\mathcal{G}_\theta$ such that

\begin{equation}\label{eq:growth}
    \norm{\mathcal{G}(v)-\mathcal{G}_\theta(v)}_{L^2(D)}\leq Cp^{-\lambda}\qquad \text{and} \qquad \abs{\mathcal{G}_\theta(v)}_{C^r(D)}\leq Cp^{\sigma(r)}\quad \forall r\in\mathbb{N}, v\in\mathcal{X}. 
\end{equation}
Then for all $\beta\in\mathbb{R}$ with $0<\beta\leq \frac{(r-\ell)\lambda^*-\ell\sigma(r)}{r}$ there exists a constant $C^*>0$ such that for all $v\in \mathcal{X}$ and $p\in\mathbb{N}$

it holds that
\begin{equation}\label{eq:deeponet-to-pido}
    \norm{\mathcal{L}(\mathcal{G}_\theta(v))}_{L^2(D)} \leq C^*p^{-\beta}.
\end{equation}

For suitable $D^{\bm{\alpha}}$, use {\bf SM} Lemma \ref{lem:derivatives} with $q=2$, $f_1=\mathcal{G}(v)$ and $f_2=\mathcal{G}_\theta(v)$ together with \eqref{eq:growth} to find
\begin{equation}
    \norm{D^{\bm{\alpha}}(\mathcal{G}(v)-\mathcal{G}_\theta(v))}_{L^2(D)} \leq C(r,\lambda)(p^{-\lambda}h^{-\ell} + p^{\sigma(r)}h^{r-\ell}). 
\end{equation}
Let $\beta\in\mathbb{R}$ with $0<\beta\leq \frac{(r-\ell)\lambda^*-\ell\sigma(r)}{r}$. We carefully balance terms by setting $h=p^{-\frac{\sigma(r)+\beta}{r-\ell}}$ and $\lambda = \frac{\ell}{r-\ell}\sigma(r)+\frac{r}{r-\ell}\beta$ to find \eqref{eq:deeponet-to-pido}. Conclude using Assumption \ref{ass:diff-operator}.

\label{thm:nn-to-pido}
Let $s,r\in\mathbb{N}$, $T>0$, let $\mathcal{G}: C^r(\mathbb{T}^d)\to C^{(s,r)}([0,T]\times \mathbb{T}^d)$ be an operator that maps a function $u_0$ to the solution $u$ of the PDE \eqref{eq:PDE} with initial condition $u_0$, let Assumption \ref{ass:nn} and Assumption \ref{ass:stability} be satisfied {\color{black}and let $p^*\in\{2,\infty\}\setminus\{p\}$}. There exists a constant $C>0$ such that for every $Z,N,M\in\mathbb{N}$, $\varepsilon, \rho>0$ there is an DeepONet $\mathcal{G}_\theta: C^r(\mathbb{T}^d)\to L^2([0,T]\times\mathbb{T}^d)$ with $Z^d$ sensors with accuracy, 
\begin{equation}
    \norm{\mathcal{G}(v)-\mathcal{G}_\theta(v)}_{L^2([0,T]\times\mathbb{T}^d)} \leq CM^{\rho}(\norm{u}_{C^{(s,0)}}M^{-s}+M^{s-1}(\varepsilon+C^\varepsilon_{\mathrm{stab}}Z^{-r+d/p^*}+C^{CB}_{\varepsilon,r}N^{-r}))
\end{equation}
and if additionally Assumption \ref{ass:partition} and Assumption \ref{ass:diff-operator} hold then,
\begin{equation}
    \norm{\mathcal{L}(\mathcal{G}_\theta(v))}_{L^2([0,T]\times\mathbb{T}^d)} \leq CM^{k+\rho}(\norm{u}_{C^{(s,\ell)}}M^{-s}+M^{s-1}N^\ell(\varepsilon+C^\varepsilon_{\mathrm{stab}}Z^{-r+d/p^*}+C^{CB}_{\varepsilon,r}N^{-r})), 
\end{equation}
for all $v$. Moreover, it holds that, $\mathrm{depth}({\bm{\beta}})=\mathrm{depth}(\mathcal{U}^\varepsilon)$, $\mathrm{width}({\bm{\beta}}) = \mathcal{O}(M(Z^d+N^d\mathrm{width}(\mathcal{U}^\varepsilon)))$, 
$\mathrm{depth}({\bm{\tau}}) = 3$ and $\mathrm{width}({\bm{\tau}}) = \mathcal{O}(MN^d(N+\ln(N)))$.

\label{thm:generalization}
For $R>0$ and $d_\Theta\in\mathbb{N}$, let $\Theta = [-R,R]^{d_\Theta}$ be the set of trainable parameters, and for every training set $\mathcal{S}$, let $\theta^*(\mathcal{S}) \in\Theta$ be an (approximate) minimizer of $\theta\mapsto\mathcal{E}_T(\theta,\mathcal{S})^2$, assume that $\theta\mapsto\mathcal{E}_G(\theta,\mathcal{S})^2$ and $\theta\mapsto\mathcal{E}_T(\theta)^2$ are bounded by $c>0$ and Lipschitz continuous with Lipschitz constant $\mathfrak{L}>0$.  
If $n\geq 2c^2e^8/(2R\mathfrak{L})^{{d_\Theta}/2}$ then it holds that 
\begin{equation}\label{eq:generalization}
    \E{\mathcal{E}_G(\theta^*(\mathcal{S}))^2} \leq \E{\mathcal{E}_T(\theta^*(\mathcal{S}),\mathcal{S})^2} + \sqrt{\frac{2c^2(d_\Theta+1)}{n}\ln(R\mathfrak{L}\sqrt{n})}.
\end{equation}

\label{thm:kolmogorov}
Assume that Setting \ref{set:kolmogorov} holds. For every $\sigma,\varepsilon>0$ and $d\in\mathbb{N}$, there is a tanh neural network $u_\theta$ of depth $\mathcal{O}(\mathrm{depth}({\widehat{u}}_0))$ and width $\mathcal{O}(\mathrm{poly}(d\rho_d)\varepsilon^{-(2+\beta)\frac{r+\sigma}{r-2}\frac{s+1}{s-1}-\frac{1+\sigma}{s-1}})$ such that,
\begin{equation}
    \norm{\mathcal{L}(u_\theta)}_{L^2([0,T]\times [0,1]^d)} + \norm{u_\theta-u}_{L^2(\partial([0,T]\times [0,1]^d))} \leq \varepsilon.
\end{equation}

\label{thm:AC-pinn}
Assume Setting \ref{set:AC}. For every $\sigma, \varepsilon>0$ and $d\in\mathbb{N}$ there is a tanh neural network $u_\theta$ of depth $\mathcal{O}(\mathrm{depth}({\widehat{u}}_0)+\mathrm{poly}(d)\ln(1/\varepsilon))$ and width $\mathcal{O}(\mathrm{poly}(d)\varepsilon^{-(2+\beta)\frac{r+\sigma}{r-2}\frac{s+1}{s-1}-\frac{1+\sigma}{s-1}})$ such that,
\begin{equation}
     \norm{\mathcal{L}(u_\theta)}_{L^2([0,T]\times\mathbb{T}^d, \mu)} + \norm{u-u_\theta}_{L^2(\partial([0,T]\times\mathbb{T}^d, \mu^*))} \leq  \varepsilon. 
\end{equation}

\label{thm:AC-operator}
Assume Setting \ref{set:AC} and let $\mathcal{G}: \mathcal{X}\to C^{r}(\mathbb{T}^d):u_0\mapsto u(T)$ and $\mathcal{G}^*: \mathcal{X} \to C^{(2,r)}([0,T]\times \mathbb{T}^d):u_0\mapsto u$. For every $\sigma, \varepsilon>0$, there exists a DeepONets $\mathcal{G}_\theta$ and $\mathcal{G}_\theta^*$ such that
\begin{equation}
    \norm{\mathcal{G}-\mathcal{G}_\theta}_{L^2(\mathbb{T}^d\times \mathcal{X})} \leq \varepsilon, \qquad \norm{\mathcal{L}(\mathcal{G}^*_\theta)}_{L^2([0,T]\times\mathbb{T}^d\times \mathcal{X})} \leq \varepsilon. 
\end{equation}
Moreover, for $\mathcal{G}_\theta$ we have $\mathcal{O}(\varepsilon^{-\frac{d+\sigma}{r}})$ sensors and,
\begin{equation}
    \begin{array}{ll}
    \mathrm{width}({\bm{\beta}})= \mathcal{O}( \varepsilon^{-\frac{(d+\sigma)(2+\beta)}{r}}), & \mathrm{depth}({\bm{\beta}}) =\mathcal{O}( \ln(1/\varepsilon)), \\ 
    \mathrm{width}({\bm{\tau}}) = \mathcal{O}(\varepsilon^{-\frac{d+1+\sigma}{r}}), & \mathrm{depth}({\bm{\tau}}) = 3,
    \end{array}
\end{equation}
whereas for $\mathcal{G}^*_\theta$ we have $\mathcal{O}(\varepsilon^{-\frac{(3+\sigma)d}{r-2}})$ sensors and,
\begin{equation}
    \begin{array}{ll}
    \mathrm{width}({\bm{\beta}})= \mathcal{O}( \varepsilon^{-1-\frac{(3+\sigma)(d+r(2+\beta))}{r-2}}), & \mathrm{depth}({\bm{\beta}}) =\mathcal{O}( \ln(1/\varepsilon)), \\ 
    \mathrm{width}({\bm{\tau}}) = \mathcal{O}(\varepsilon^{-1-\frac{(3+\sigma)(d+1)}{r-2}}), & \mathrm{depth}({\bm{\tau}}) = 3.
    \end{array}
\end{equation}

\label{thm:linear-pido}
Assume the setting above and that of Assumption \ref{ass:diff-operator}, and assume that $\mathcal{G}(v)\in C^{\ell+1}(\mathbb{T}^d)$ for all $v\in \mathcal{X}$. For all $\beta>0$ there exists a constant $C>0$ such that for any $p\in\mathbb{N}$ there exists a DeepONet $\mathcal{G}_\theta$ with $p$ sensors and branch and trunk nets such that
\begin{equation}
    \norm{\mathcal{L}(\mathcal{G}_\theta))}_{L^2(L^2(\mathbb{T}^d),\mu)}\leq Cp^{-\beta}.
\end{equation}
Moreover, $\mathrm{size}({\bm{\tau}}) \leq Cp^{\frac{d+1}{d}}$, $\mathrm{depth}({\bm{\tau}}) = 3$, $\mathrm{size}({\bm{\beta}}) \leq p$ and $\mathrm{depth}({\bm{\beta}}) = 1$.

we define a finite difference operator $\Delta^{{\bm{\alpha}},r}_h$ as, 
