for a constant $C(s,d)>0$ that only depends on $s$ and $d$.

\label{lem:pol-tanh}
Let $k\in\mathbb{N}_0, s\in 2\mathbb{N}-1$,  ${\color{black}M>0}$ and define $f_p:[-M,M]\to\mathbb{R}: x\mapsto x^p$ for all $p\in \mathbb{N}$. For every $\varepsilon>0$, there exists a shallow tanh neural network $\psi_{s,{\color{black}\varepsilon}} : {\color{black}[-M,M]}\to \mathbb{R}^s$ of width $\frac{3(s+1)}{2}$ such that 
\begin{equation}
    \max_{p\leq s} \ck{f_p- (\psi_{s,\varepsilon})_p} \leq\varepsilon.
\end{equation}

\label{lem:mult-shallow}
Let $d\in \mathbb{N}$, $k\in \mathbb{N}_0$ and $M>0$. Then for every $\varepsilon>0$, there exist a shallow tanh neural network $\widehat{\times}_d^\varepsilon: [-M,M]^d\to\mathbb{R}$ of width $3\left\lceil\frac{d+1}{2}\right\rceil\abs{P_{d,d} }$ (or $4$ if $d=2$) such that
\begin{equation}
   \ck{\widehat{\times}_d^\varepsilon(x)-\prod_{i=1}^d x_i} \leq \varepsilon.
\end{equation}

\label{lem:derivatives}
Let $q\in [1,\infty]$, $r, \ell\in\mathbb{N}$ with $\ell\leq r$ and $f_1, f_2 \in C^{(0,r)}([0,T]\times D)$. If Assumption \ref{ass:partition} holds then there exists a constant $C(r)>0$ such that for any ${\bm{\alpha}}\in\mathbb{N}^d_0$ with $\ell := \norm{{\bm{\alpha}}}_1$ it holds that
\begin{equation}
    \norm{D^{\bm{\alpha}}_x (f_1-f_2)}_{L^q} \leq C(\norm{f_1-f_2}_{L^q}h^{-\ell} + \max_{j=1,2}\abs{f_j}_{C^{(0,r)}}h^{r-\ell})\qquad \forall h>0.
\end{equation}

From the triangle inequality and \eqref{eq:accuracy-FD} the existence of a constant $C(r)>0$ follows such that,
\begin{equation}
    \begin{split}
        \norm{D^{\bm{\alpha}}_x (f_1-f_2)}_{L^q} &\leq  \max_{j=1,2} \norm{D^{\bm{\alpha}} f_j-h^{-\ell}\cdot\Delta^{{\bm{\alpha}},r}_h[f_j]}_{L^q} + C(r) h^{-\ell} \norm{f_1-f_2}_{L^q} \\
            &\leq c_{\ell,r} \max_{j=1,2} \abs{f_j}_{C^{(0,r)}} h^{r-\ell} + C(r) h^{-\ell} \norm{f_1-f_2}_{L^q}.\qedhere
    \end{split}
\end{equation}

\begin{equation}
    \begin{split}
        \norm{D^{\bm{\alpha}}_x (f_1-f_2)}_{L^q} &\leq  \max_{j=1,2} \norm{D^{\bm{\alpha}} f_j-h^{-\ell}\cdot\Delta^{{\bm{\alpha}},r}_h[f_j]}_{L^q} + C(r) h^{-\ell} \norm{f_1-f_2}_{L^q} \\
            &\leq c_{\ell,r} \max_{j=1,2} \abs{f_j}_{C^{(0,r)}} h^{r-\ell} + C(r) h^{-\ell} \norm{f_1-f_2}_{L^q}.\qedhere
    \end{split}
\end{equation}

\label{lem:wlog-faa-di-bruno}
Using the notation of the proof of Theorem \ref{thm:nn-to-pinn} (\textbf{SM} \ref{app:nn-to-pinn}), it holds that 
\begin{equation}
    \norm{D^{(k,{\bm{\alpha}})}(\Tilde{u}-{\widehat{u}})}_{C^0} \leq \delta.
\end{equation}

Using the Faà di Bruno formula \cite{constantine1996multivariate} and its consequences for estimating the norms of derivatives of compositions \cite[Lemma A.7]{deryck2021approximation} one can prove for sufficiently regular functions $g_1,g_2,h_1,h_2$ and a suitable multi-index ${\bm{\beta}}$ estimates of the form,
\begin{equation}
    \norm{D^{{\bm{\beta}}}(g_1\circ h_1-g_2\circ h_2)}_{C^0} \leq C(\norm{g_1-g_2}_{C^{\norm{{\bm{\beta}}}_1}}+\norm{h_1-h_2}_{C^{\norm{{\bm{\beta}}}_1}}), 
\end{equation}
assuming that the compositions are well-defined and where the constant $C>0$ may depend on $g_1,g_2,h_1,h_2$ and their derivatives. Using this theorem we can prove that
\begin{equation}\label{eq:wlog1}
    \norm{D^{(k,{\bm{\alpha}})}{\widehat{u}}-D^{(k,{\bm{\alpha}})}\sum_{m=1}^M \sum_{i=0}^{s-1} \frac{\Delta^{i,s-i}_{1/M,t}[{\widehat{u}}^\varepsilon_m](t_m,x)}{M^{-i} i!}\cdot \widehat{\varphi}_i^\delta(t-t_m)\cdot \Phi^M_m(t)} < C\delta. 
\end{equation}
Because the size of the neural network $\widehat{\times}_\delta$ in the definition of ${\widehat{u}}$ does not depend on its accuracy $\delta$ (see Lemma \ref{lem:mult-shallow}) we can rescale $\delta$ and therefore set $C=1/2$ in the above inequality. 

Next, we observe that,
\begin{align}\label{eq:wlog2}
    \begin{split}
        &D^{(k,{\bm{\alpha}})}\sum_{m=1}^M \sum_{i=0}^{s-1} \frac{\Delta^{i,s-i}_{1/M,t}[{\widehat{u}}^\varepsilon_m](t_m,x)}{M^{-i} i!}\cdot (\widehat{\varphi}_i^\delta-\varphi_i)(t-t_m)\cdot \Phi^M_m(t) \\
        &\quad = \sum_{m=1}^M \sum_{i=0}^{s-1} \frac{\Delta^{i,s-i}_{1/M,t}[D^{\bm{\alpha}}_x {\widehat{u}}^\varepsilon_m](t_m,x)}{M^{-i} i!}\cdot \sum_{n=0}^k \binom{k}{n}\partial_t^n(\widehat{\varphi}_i^\delta-\varphi_i)(t-t_m)\cdot \partial_t^{k-n}\Phi^M_m(t)
    \end{split}
\end{align}
Analogously to before, because the sizes of the neural networks ${\widehat{\varphi}}_i^\delta$ are independent of their accuracy $\delta$ we can rescale $\delta$ such that $\norm{\eqref{eq:wlog2}}_{C^0}\leq \delta/2$. The claim follows by the triangle inequality,
\begin{equation}
    \norm{D^{(k,{\bm{\alpha}})}(\Tilde{u}-{\widehat{u}})}_{C^0} \leq\norm{\eqref{eq:wlog1}}_{C^0}+ \norm{\eqref{eq:wlog2}}_{C^0}\leq \delta.
\end{equation}

\label{lem:newton-pol}
Let $\Delta^{k,s}_{h,t}$ be a finite difference operator cf. Section \ref{sec:FD} and \textbf{SM} \ref{app:FD}, let $1\leq j\leq d$, let $1\leq q\leq \infty$, let $\ell \in \mathbb{N}_0$ and let ${\bm{\alpha}}\in\mathbb{N}^d_0$ with $\norm{{\bm{\alpha}}}_1=\ell$. Let $u,{\widehat{u}}\in C^{(s,\ell)}([-2h,2h]\times D)$ such that for all $t\in [-2h,2h]$,
\begin{equation}\label{eq:newton-u-uhat}
    \norm{D^{{\bm{\alpha}}}_x(u(t,\cdot)-{\widehat{u}}(t,\cdot))}_{L^q(D)} \leq \varepsilon. 
\end{equation}
Then there exists $c_s>0$ holds that, 
\begin{equation}
    \norm{D^{k,{\bm{\alpha}}}\left(\sum_{i=0}^{s-1}\frac{\Delta^{i,s-i}_{h,t}[{\widehat{u}}](0,x)}{h^i i!}t^i-u(t,\cdot)\right)}_{L^q}\leq c_{s}\left(\varepsilon h^{-k}+\abs{D^{{\bm{\alpha}}}_xu}_{C^{(s,0)}}h^{s-k}\right).
\end{equation}

Let $t\in[-2h,2h]$, ${\bm{\alpha}}\in\mathbb{N}^d_0$ with $\norm{{\bm{\alpha}}}_1=\ell$ and $x\in\mathbb{R}^d$ be arbitrary. We first observe that,
\begin{equation}
   D^{k,{\bm{\alpha}}}\sum_{i=0}^{s-1}\frac{\Delta^{i,s-i}_{h,t}[u](0,x)}{h^i i!}t^i = \sum_{i=k}^{s-1}\frac{\Delta^{i,s-i}_{h,t}[D^{{\bm{\alpha}}}_x u](0,x)}{h^i (i-k)!}t^{i-k}. 
\end{equation}
Taylor's theorem then guarantees the existence of $\xi_{t,x}\in[-2h,2h]$ such that
\begin{equation}
\begin{split}
    &D^{k,{\bm{\alpha}}}\left(\sum_{i=0}^{s-1}\frac{\Delta^{i,s-i}_{h,t}[u](0,x)}{h^i i!}t^i-u(t,\cdot)\right)\\
    &\quad = \sum_{i=0}^{s-1-k}\left[\frac{\Delta^{i+k,s-i-k}_{h,t}[D^{{\bm{\alpha}}}_x u](0,x)}{h^{i+k} i!}t^{i}-\frac{D^{i+k,{\bm{\alpha}}} u(0,x)}{i!}t^i\right] + \frac{D^{s,{\bm{\alpha}}}u(\xi_{t,x},x)}{(s-k)!}t^{s-k}. 
\end{split}
\end{equation}
Now observe that because of assumption \eqref{eq:newton-u-uhat} and the definition and properties \eqref{eq:accuracy-FD} of the finite difference operator, there exists a constant $C_s>0$ such that,
\begin{equation}
\begin{split}
    &\norm{\Delta^{i+k,s-i-k}_{h,t}[D^{{\bm{\alpha}}}_x {\widehat{u}}](0,x)-\Delta^{i+k,s-i-k}_{h,t}[D^{{\bm{\alpha}}}_x u](0,x)}_{L^q} \leq C_s\varepsilon,\\
    &\abs{\frac{\Delta^{i+k,s-i-k}_{h,t}[D^{{\bm{\alpha}}}_x u](0,x)}{h^{i+k}} - D^{i+k,{\bm{\alpha}}}u(0,x)} \leq C_s \abs{D^{{\bm{\alpha}}}_xu}_{C^{(s,0)}}h^{r-i-k}.
\end{split}
\end{equation}
Combining all previous results provides us with the existence of a constant $c_s>0$ such that,
\begin{equation}
    \begin{split}
        &\norm{D^{k,{\bm{\alpha}}}\left(\sum_{i=0}^{s-1}\frac{\Delta^{i,s-i}_{h,t}[{\widehat{u}}](0,x)}{h^i i!}t^i-u(t,\cdot)\right)}_{L^q}\\
        &\quad \leq \sum_{i=0}^{s-1-k}\left[\frac{C_s\varepsilon}{h^{i+k} i!}h^i + \frac{C_s }{i!}\abs{D^{{\bm{\alpha}}}_xu}_{C^{(s,0)}}h^{s-i-k}h^i\right] + \frac{1}{(s-k)!}\abs{D^{{\bm{\alpha}}}_xu}_{C^{(s,0)}}h^{s-k}\\
        &\quad \leq c_s\left(\varepsilon h^{-k}+\abs{D^{{\bm{\alpha}}}_xu}_{C^{(s,0)}}h^{s-k}\right). 
    \end{split}
\end{equation}

\label{def:pou}
Let $C>0$, $N\in\mathbb{N}$, $0<\varepsilon<1$ and $\alpha=\ln(CN^k/\varepsilon)$. For every $1\leq j\leq N$, we define the function $\Phi_j^N:[0,T]\to[0,1]$ by
\begin{align}\label{eq:pou-def}
\begin{split}
    \Phi_1^N(t) &= \frac{1}{2}-\frac{1}{2}\sigma\left(\alpha\left(t-\frac{T}{N}\right)\right),\\
    \Phi_j^N(t) &= \frac{1}{2}\sigma\left(\alpha\left(t-\frac{T(j-1)}{N}\right)\right) - \frac{1}{2}\sigma\left(\alpha\left(t-\frac{Tj}{N}\right)\right),\\
    \Phi_N^N(t) &= \frac{1}{2}\sigma\left(\alpha\left(t-\frac{T(N-1)}{N}\right)\right)+\frac{1}{2}.
    \end{split}
\end{align}

\label{thm:tanh-approximation}
Let $k\in\mathbb{N}\cup\{0\}$, $q\in\{2,\infty\}$, $\xi>0$ and $s\in \mathbb{N}$. Let $\mu$ be a probability measure on $D$ and let $f\in C^s([0,T], L^q(\mu))$. 
Assume that for every $0\leq \ell \leq k$ there is a constant $\mathcal{C}^*_\ell>0$ for which it holds that for every $N\in\mathbb{N}$ there exist functions $\{p_j^N\}_{j=1}^N$ that satisfy for all $ 1\leq j\leq N$,
\begin{align}\label{eq:pkn-acc-sobolev}
\begin{split}
    \abs{f-p_j^N}_{C^\ell(J^N_j, L^q(\mu))}=\max_{t\in \left[\frac{(j-2)T}{N},\frac{(j+1)T}{N}\right]}\norm{D_t^\ell(f(t,\cdot)-p_j^N(t,\cdot))}_{L^q(\mu)} &\leq   \mathcal{C^*_{\ell}}N^{-s+\ell}+\xi.
\end{split}
\end{align}
Let $\mathcal{C}_k:=\max\{\max_{0\leq \ell \leq k}\mathcal{C}^*_\ell, \hkunit{f},1\}$. There exists a constant $C(k)>0$ that only depends on $k$ such that for all $N\geq 3$ it holds that,
\begin{equation}
\begin{split}
    \hkunit{f-\sum_{j=1}^N p_j^N\cdot \Phi^{N}_j} \quad \leq C \ln^k\left(N\right)\left[\frac{\mathcal{C}_k}{N^{s-k}} + \xi N^k\right]. 
\end{split}
\end{equation}

We follow the proof of \cite[Theorem 5.1]{deryck2021approximation}. All steps of the proofs are identical, with the only difference being that the $W^{k,\infty}([0,1]^d)$-norm of \cite{deryck2021approximation} is replaced by the ${C^k([0,T], L^2(\mu))}$-norm in this work. Following \cite{deryck2021approximation}, one divides the domain $[0,T]$ into intervals $I_i^N = [t_{i-1}, t_i]$, with $t_i=iT/N$ and $N\in\mathbb{N}$ large enough. On each of these intervals, $f$ locally can be  approximated (in Sobolev norm) by $p_j^N$, by virtue of the assumptions of the theorem. A global approximation can then be constructed by multiplying each $p_j^N$ with an approximation of the indicator function of the corresponding intervals and summing over all intervals. 

We now highlight the main steps in the proof. 
\textit{Step 2a} (as in \cite{deryck2021approximation}) results in the following estimate,
\begin{align}
    \begin{split}
        \hki{f-\sum_{j=1}^N f \cdot \Phi^{N}_j} \leq C \hki{f} \left(\varepsilon +N^{k+1} \ln^k\left(\frac{CN^k}{\varepsilon}\right)\varepsilon\right). 
    \end{split}
\end{align}
\textit{Step 2b} results in the estimate, 
\begin{align}
    \begin{split}
       \hki{\sum_{j=1}^N (f -p_j^N)\cdot \Phi^{N,d}_j}\leq  C \ln^k\left(\frac{CN^k}{\varepsilon}\right)\left[\frac{\mathcal{C}_k}{N^{s-k}} + \xi N^k + \mathcal{C}_k N^{k+1} {\varepsilon}\right],
    \end{split}
\end{align}
Putting everything together, we find that if $CN^k\geq {\varepsilon}e$,
\begin{equation}
\begin{split}
    &\hkunit{f-\sum_{j=1}^N p_j^N\cdot \Phi^{N}_j} \\&\quad \leq C \ln^k\left(\frac{CN^k}{\varepsilon}\right)\left[(\hki{f}+\mathcal{C}_k)N^{k+1}\varepsilon+ \frac{\mathcal{C}_k}{N^{s-k}} + \xi N^k\right]. 
\end{split}
\end{equation}
In particular, if we set $N^{k+1}\varepsilon = N^{-s+k}$ and $N\geq 3$, then we find that
\begin{equation}
\begin{split}
    \hkunit{f-\sum_{j=1}^N p_j^N\cdot \Phi^{N}_j} \quad \leq C \ln^k\left(N\right)\left[\frac{\hki{f}+\mathcal{C}_k}{N^{s-k}} + \xi N^k\right]. 
\end{split}
\end{equation}

\label{lem:equivalence}
Let $\mathcal{G}_\theta:\mathcal{X} \to \mathcal{H}$ be a tanh FNO with grid size $N\in\mathbb{N}$ and let $B>0$. For every $\varepsilon>0$, there exists a tanh DeepONet $\mathcal{G}_\theta^*: \mathcal{X}\to\mathcal{H}$ with $N^d$ sensors and $N^d$ branch and trunk nets such that
\begin{equation}
    \sup_{\norm{v}_{L^\infty}\leq B}\sup_{x \in \mathbb{T}^d} \abs{\mathcal{G}_\theta^*(v)(x)-\mathcal{G}_\theta(v)(x)}\leq \varepsilon. 
\end{equation}
Furthermore, $\mathrm{width}({\bm{\beta}}) \sim N^d$, $\mathrm{depth}({\bm{\beta}}) \sim \ln(N)$, $\mathrm{width}({\bm{\tau}}) \sim N^{d}(N+\ln(N/\varepsilon))$ and $\mathrm{depth}({\bm{\tau}}) = 3$.

\textbf{Step 1: construction. }
To define the approximation, we divide $[0,T]$ into $M$ subintervals of the form $[t_{m-1},t_m]$, where $t_m = mT/M$ with $1\leq m\leq M$. One could approximate $u$ on every subinterval by an $s$-th order accurate Taylor approximation around $t_m$, provided that one has access to $D^i_t u(\cdot, t_m)$ for $0\leq i \leq s-1$. As those values are unknown, we resort to the finite difference approximation $D^i_t u(\cdot, t_m)\approx M^i\cdot \Delta^{i,s-i}_{1/M,t}[\mathcal{U}^\varepsilon(u_0,t_m)]$, which is a neural network. See \textbf{SM} \ref{app:FD} for an overview of the notation for finite difference operators. Moreover, we replace the univariate monomials $\varphi_i:[0,T]\to\mathbb{R}: t\mapsto t^i$ in the Taylor approximation by neural networks $\widehat{\varphi}_i^\delta:[0,T]\to\mathbb{R}$ with $\Vert\varphi_i-\widehat{\varphi}_i^\delta\Vert_{C^{k+1}}\lesssim \delta$. Lemma \ref{lem:pol-tanh} guarantees that the output of $(\widehat{\varphi}_i^\delta)_{i=1}^{s-1}$ can be obtained using a shallow network with width $2(s+1)$ (independent of $\delta$). The multiplication operator is replaced by a shallow neural network $\widehat{\times}_\delta: [-a,a]^2\to\mathbb{R}$ (for suitable $a>0$) for which $\Vert\times-\widehat{\times}_\delta\Vert_{C^{k+1}}\lesssim \delta$. By Lemma \ref{lem:mult-shallow} only four neurons are needed for this network. This results in the following approximation for $f\in C^0([0,T]\times D)$, 
\begin{equation}
     \widehat{N}^{\delta}_m[f](t,x) := \sum_{i=0}^{s-1} \widehat{\times}_\delta\left(\frac{\Delta^{i,s-i}_{1/M,t}[f](t_m,x)}{M^{-i} i!}, \widehat{\varphi}_i^\delta(t-t_m)\right) \quad \forall t\in [0,T], \: x\in D, \: 1\leq m\leq M. 
\end{equation}
Next, we patch together these individual approximations by (approximately) multiplying them with a NN approximation of a partition of unity, denoted by $\Phi^M_1, \ldots, \Phi^M_M:[0,T]\to[0,1]$, as introduced in Definition \ref{def:pou} in \textbf{SM} \ref{app:general}. Every $\Phi_m^M$ can be thought of as a NN approximation of the indicator function on $[t_{m-1},t_m]$. For any $\varepsilon,\delta>0$, we then define our final neural network approximation ${\widehat{u}}:[0,T]\times D\to \mathbb{R}$ as,
\begin{equation}\label{eq:def-pinn}
\begin{split}
     {\widehat{u}}(t,x) := \sum_{m=1}^M \widehat{\times}_\delta \left(\widehat{N}^{\delta}_m[\mathcal{U}^\varepsilon(u_0,t_m)](t,x), \Phi^M_m(t)\right) \quad \forall t\in [0,T], \: x\in D.
\end{split}
\end{equation}

\textbf{Step 2: error estimate.} In order to facilitate the proof, we introduce the intermediate approximations $\Tilde{u}:[0,T]\times D\to \mathbb{R}$ and $N_m:C^0(D)\times [0,T]\times D\to \mathbb{R}$ by, 
\begin{equation}
     \Tilde{u}(t,x) := \sum_{m=1}^M N_m[{\widehat{u}}^\varepsilon_m](t,x)\cdot \Phi^M_m(t) := \sum_{m=1}^M \sum_{i=0}^{s-1} \frac{\Delta^{i,s-i}_{1/M,t}[{\widehat{u}}^\varepsilon_m](t_m,x)}{M^{-i} i!}\cdot \varphi_i(t-t_m)\cdot \Phi^M_m(t), 
\end{equation}
where ${\widehat{u}}^\varepsilon_m = \mathcal{U}^\varepsilon(u_0,t_m)$. Note that ${\widehat{u}}$ can be obtained from $\Tilde{u}$ by replacing the multiplication operator and the monomials by neural networks. Since these the size of these networks are independent of their accuracy $\delta$, we can assume without loss of generality that $\Vert D^{(k,{\bm{\alpha}})}(\Tilde{u}-{\widehat{u}})(t,\cdot)\Vert_{L^q}\leq \delta$ (see Lemma \ref{lem:wlog-faa-di-bruno}) for any relevant $D^{(k,{\bm{\alpha}})}$ and $t$. 

It remains to prove that $D^{(k,{\bm{\alpha}})}\Tilde{u} \approx D^{(k,{\bm{\alpha}})}u$. 
Combining the observation that $D^{(k,{\bm{\alpha}})}N_m[{\widehat{u}}^\varepsilon_m] = D_t^k N_m[D^{\bm{\alpha}}_x{\widehat{u}}^\varepsilon_m]$ with Lemma \ref{lem:newton-pol} lets us conclude that for all $0\leq k\leq s-1$ and $t\in[t_{m-2}, t_{m+2}]$,
\begin{equation}

    \norm{D^{(k,{\bm{\alpha}})}( N_m[{\widehat{u}}^\varepsilon_m](t,\cdot)-u(t,\cdot))}_{L^q} \leq C(r)M^k(\norm{D^{\bm{\alpha}}_x({\widehat{u}}^\varepsilon_m-u)(\cdot,t_m)}_{L^q}+\abs{u}_{C^{(s,\ell)}}M^{-s})
\end{equation}
We use Theorem \ref{thm:tanh-approximation} with $f\leftarrow u$, $p_j^N \leftarrow  N_m[D^{\bm{\alpha}}_x{\widehat{u}}^\varepsilon_m]$, $\xi\leftarrow C(r)M^{k} \norm{D^{\bm{\alpha}}_x({\widehat{u}}^\varepsilon_m-u)(\cdot,t_m)}_{L^q}$, $\mathcal{C}^*_\ell \leftarrow C(s)\abs{u}_{C^{(k,\ell)}}$, $N\leftarrow M$ to find that, 
\begin{equation}
    \norm{D^{(k,{\bm{\alpha}})}({\widehat{u}}-u)}_{L^q} \leq C\ln^k(M)(\norm{u}_{C^{(s,\ell)}}M^{k-s}+M^{2k}\norm{D^{\bm{\alpha}}_x({\widehat{u}}^\varepsilon_m-u)(\cdot,t_m)}_{L^q}), 
\end{equation}
where $C(r,s)>0$ only depend on $r$ and $s$. Finally, using Lemma \ref{lem:derivatives} to bound $\norm{D^{\bm{\alpha}}_x({\widehat{u}}^\varepsilon_m-u)(\cdot,t_m)}_{L^q}$ and combining this with  Assumption \ref{ass:nn} proves \eqref{eq:pinn-acc}. 

\textbf{Step 3: size estimate.} The following holds, 
\begin{equation}
    \mathrm{depth}({\widehat{u}})\leq C\mathrm{depth}(\mathcal{U}^\varepsilon), \mathrm{width}({\widehat{u}}) \leq CM \mathrm{width}(\mathcal{U}^\varepsilon). 
\end{equation}

\begin{equation}
     \widehat{N}^{\delta}_m[f](t,x) := \sum_{i=0}^{s-1} \widehat{\times}_\delta\left(\frac{\Delta^{i,s-i}_{1/M,t}[f](t_m,x)}{M^{-i} i!}, \widehat{\varphi}_i^\delta(t-t_m)\right) \quad \forall t\in [0,T], \: x\in D, \: 1\leq m\leq M. 
\end{equation}

\textbf{Step 1: construction. }
Let $N\in\mathbb{N}$, let $\mathcal{E}_N: C^0(T^d)\to \mathbb{R}^{\abs{\mathcal{J}_N}}$ be an encoder and $\mathcal{Q}_N: \mathbb{R}^{\abs{\mathcal{J}_N}}\to L^2_N$ be a trigonometric polynomial interpolation operator, cf. \textbf{SM} \ref{app:trig-pol}. If we let ${\widehat{\mathcal{G}}} = \mathcal{U}^\varepsilon \circ \mathcal{Q}_N \circ \mathcal{E}_N$ then we can define an FNO $\mathcal{G}_\theta: L^2_N(\mathbb{T}^d)\to L^2_N(\mathbb{T}^d)$ as $\mathcal{G}_\theta(u_0)(x) =  (\mathcal{Q}_N\circ \mathcal{E}_N \circ {\widehat{\mathcal{G}}})(u_0)(x)$. 

\textbf{Step 2: error estimate.}
We decompose the $L^2$-error of the FNO using the triangle inequality and the inequality $\Vert\mathcal{U}^\varepsilon-{\widehat{\mathcal{G}}}\Vert_{L^2}\leq C^\varepsilon_{\mathrm{stab}}\norm{u_0-\mathcal{Q}_N\circ\mathcal{E}_N\circ u_0}_{L^p}$, which follows from Assumption \ref{ass:stability},
\begin{align}\label{eq:triangle-deeponet}
\begin{split}
\norm{\mathcal{G}-\mathcal{G}_\theta}_{L^2}
&\leq \norm{\mathcal{G}-\mathcal{U}^\varepsilon}_{L^2} + C^\varepsilon_{\mathrm{stab}}\norm{u_0-\mathcal{Q}_N\circ\mathcal{E}_N\circ u_0}_{L^p}+ \Vert{\widehat{\mathcal{G}}}-\mathcal{G}_\theta\Vert_{L^2}.
\end{split}
\end{align}

First, we find using a Sobolev embedding result (Lemma \ref{lem:sobolev-embedding}) and Lemma \ref{lem:acc-trig-pol} that,
\begin{equation}\label{eq:QEu0}
     \norm{u_0-(\mathcal{Q}_N\circ\mathcal{E}_N)(u_0)}_{L^p}\leq  \norm{u_0-(\mathcal{Q}_N\circ\mathcal{E}_N)(u_0)}_{H^{d/p^*}} \leq C(d,r) N^{-r+d/p^*}\norm{u_0}_{H^{r}},
\end{equation}
where $p^*$ is such that $1/p+1/p^*=1/2$. Next, we observe that for any $u_0\in\mathcal{X}$ with $\norm{u_0}_{C^r}\leq B$ that $\norm{(\mathcal{Q}_N\circ\mathcal{E}_N)(u_0)}_{H^r(\mathbb{T}^d)} \leq C B=:\Bar{B}$. Hence, by applying Lemma \ref{lem:acc-trig-pol} to the second and last term of \eqref{eq:triangle-deeponet} we find that,
\begin{equation}
    \norm{\mathcal{G}-\mathcal{G}_\theta}_{L^2}
\leq C(\varepsilon + C^\varepsilon_{\mathrm{stab}}BN^{-r+d/p^*}+ C_{\varepsilon,r}^{\Bar{B}}N^{-r}).
\end{equation}

\textbf{Step 3: size estimate. }
As for any FNO, the width is equal to $N^d\mathrm{width}(\mathcal{U}^\varepsilon)$. The depth in this case is equal to $\mathrm{depth}(\mathcal{U}^\varepsilon)$.

\textbf{Step 1: construction. }

Let $\varepsilon>0$ and $n,N\in\mathbb{N}$. We first introduce some notation. Let $\mathcal{J}_N = \{0,\ldots, 2N+1\}^d$, $\mathcal{K}_N = \{-N, \ldots, N\}^d$, let $\{\bm{\mathrm{e}}_j\}_{j\in\mathbb{N}}$ be an ordered Fourier basis, as described in \textbf{SM} \ref{app:Fourier}, and let $\{\widehat{\bm{\mathrm{e}}}_j\}_{j\in\mathbb{N}}$ be a neural network approximation of the same basis such that
\begin{equation}\label{eq:fb-nn}
    \max_{k\in\mathcal{K}_N}\norm{\bm{\mathrm{e}}_k-\widehat{\bm{\mathrm{e}}}_k}_{C^r} \leq \eta, 
\end{equation}
cf. Lemma \ref{lem:rec-fourier}. Using notation from \textbf{SM} \ref{app:trig-pol}, let $\mathcal{Q}_N:\mathbb{R}^{\abs{\mathcal{J}_N}}\to C(\mathbb{T}^d)$ be the trigonometric polynomial interpolation operator as in \eqref{eq:trig-pol} and let $\mathcal{E}_N:C(\mathbb{T}^d)\to\mathbb{R}^{\abs{\mathcal{J}_N}}$ be the encoder as in \eqref{eq:encoder}. We define
\begin{equation}\label{eq:qhat}
    {\widehat{\mathcal{Q}}}_{N}:\mathbb{R}^{\abs{\mathcal{J}_N}}\to C(\mathbb{T}^d): y \mapsto \frac{1}{\abs{\mathcal{K}_N}} \sum_{k\in \mathcal{K}_N} \sum_{j\in \mathcal{J}_N} y_j a_{k,j} \widehat{\bm{\mathrm{e}}}_k, 
\end{equation}
with coefficients $a_{k,j}$ as in \eqref{eq:trig-pol-coeff}, as a neural network approximation of $\mathcal{Q}_N$. 

Inspired by the proof of Theorem \ref{thm:nn-to-pinn} (and using its notation as well), we define ${\widehat{\mathcal{G}}}: C(\mathbb{T}^d)\to L^2(\mu)$ by
\begin{equation}
    {\widehat{\mathcal{G}}}(u_0)(t,x) =  \sum_{m=1}^M\sum_{i=0}^{s-1}  \frac{\Delta^{i,s-i}_{1/M}[\mathcal{U}^\varepsilon(\mathcal{Q}_Z\circ\mathcal{E}_Z\circ u_0, t_m)](t_m,x)}{M^{-i} i!}\cdot \varphi_i^\delta(t-t_m)   \Phi^M_m(t), 
\end{equation}
Then it holds that
\begin{equation}
\begin{split}
    (\mathcal{Q}_N\circ\mathcal{E}_N\circ{\widehat{\mathcal{G}}})(u_0)(t,x) &=  \sum_{k\in \mathcal{K}_N} \sum_{j\in \mathcal{J}_N}  \sum_{m=1}^M\sum_{i=0}^{s-1} \frac{a_{k,j}}{\abs{\mathcal{K}_N}} \frac{\Delta^{i,s-i}_{1/M}[\mathcal{U}^\varepsilon(\mathcal{Q}_Z\circ\mathcal{E}_Z\circ u_0, t_m)](t_m,x_j)}{M^{-i} i!}\cdot \Psi_{i,m,k}(t,x)\\
    \Psi_{i,m,k}(t,x) &= \varphi_i^\delta(t-t_m)   \Phi^M_m(t)  \bm{\mathrm{e}}_k(x).
\end{split}
\end{equation}
Now for every $i, m, k$ let $\Psi_{i,m,k}:[0,T]\times \mathbb{T}^d\to \mathbb{R}$ be defined as, 
\begin{equation}
    \widehat{\Psi}_{i,m,k}(t,x) = \widehat{\times}_\delta\left(\varphi_i^\delta(t-t_m),\Phi^M_m(t),\widehat{\bm{\mathrm{e}}}
    _k(x)\right), 
\end{equation}
where $\widehat{\times}_\delta$ is a neural network approximation of the multiplication operator. We can then construct a DeepONet as
\begin{equation}\label{eq:def-pido}
    \begin{split}
 \mathcal{G}_\theta(u_0)(t,x) &= \sum_{j=1}^p \beta_j(u_0)\tau_j(t,x)\\
 &= \sum_{i=0}^{s-1}\sum_{m=1}^M \sum_{k\in \mathcal{K}_N} \left[\sum_{j\in \mathcal{J}_N}   \frac{a_{k,j}}{\abs{\mathcal{K}_N}} \frac{\Delta^{i,s-i}_{1/M}[\mathcal{U}^\varepsilon(\mathcal{Q}_Z\circ\mathcal{E}_Z\circ u_0, t_m)](t_m,x_j)}{M^{-i} i!}\right] \cdot \widehat{\Psi}_{i,m,k}(t,x).
    \end{split}
\end{equation}
We see that we need to set $p=sM(2N+1)^d$ and that the trunk nets are given by $\tau_j\sim \widehat{\Psi}_{i,m,k}$, up to a different indexing. 

\textbf{Step 2: error estimate.}
First we use Assumption \ref{ass:diff-operator} to see that
\begin{equation}
    \norm{\mathcal{L}(\mathcal{G}-\mathcal{G}_\theta)}_{L^2} \leq C \sum_{k,{\bm{\alpha}}} \norm{D^{(k,{\bm{\alpha}})}(\mathcal{G}-\mathcal{G}_\theta)}_{L^2}. 
\end{equation}
Next, we observe that using Assumption \ref{ass:nn}, Assumption \ref{ass:stability} and \eqref{eq:QEu0} it holds that for all $t$,
\begin{equation}\label{eq:QEu0-Z}

    \norm{(\mathcal{U}^\varepsilon(\mathcal{Q}_Z\circ \mathcal{E}_Z\circ u_0)-\mathcal{G}(u_0))(\cdot,t)}_{L^2} \leq \varepsilon + C^\varepsilon_{\mathrm{stab}}CBZ^{-r+d/p^*}. 
\end{equation}
One can then use Theorem \ref{thm:nn-to-pinn}, but by replacing $\varepsilon$ by \eqref{eq:QEu0-Z} in the error bound \eqref{eq:pinn-acc}, to find that
\begin{equation}
    \norm{D^{(k,{\bm{\alpha}})}(\mathcal{G}-{\widehat{\mathcal{G}}})}_{L^2}\leq C\ln^k(M)(\norm{u}_{C^{(s,\ell)}}M^{k-s}+M^{2k}((\varepsilon+C^\varepsilon_{\mathrm{stab}}Z^{-r+d/p^*})h^{-\ell}+C^{CB}_{\varepsilon,\ell}h^{r-\ell}))
\end{equation}
Then, using the observation that $D^{(k,{\bm{\alpha}})}(\mathrm{Id}-\mathcal{Q}_N\circ \mathcal{E}_N){\widehat{\mathcal{G}}} = D^{\bm{\alpha}}_x(\mathrm{Id}-\mathcal{Q}_N\circ \mathcal{E}_N)D^k_t{\widehat{\mathcal{G}}}$ we find that
\begin{equation}
     \norm{D^{(k,{\bm{\alpha}})}(\mathrm{Id}-\mathcal{Q}_N\circ \mathcal{E}_N){\widehat{\mathcal{G}}}(u_0)}_{L^2} \leq CN^{-(r-\ell)}\norm{D^k_t{\widehat{\mathcal{G}}}(u_0)}_{H^{r}},
\end{equation}
which can be combined with the estimate
\begin{equation}
    \norm{D^k_t{\widehat{\mathcal{G}}}(u_0)}_{H^{r}} \leq M^{s-1}\cdot M^k \ln^k(M) \norm{\mathcal{U}^\varepsilon(\mathcal{Q}_Z\circ \mathcal{E}_Z \circ u_0)}_{H^{r}} \leq M^{s+k-1} \ln^k(M) C_{\varepsilon,r}^{\Bar{B}},
\end{equation}
where we used that for $u_0\in\mathcal{X}$ with $\norm{u_0}_{C^r}\leq B$ it holds $\norm{(\mathcal{Q}_N\circ\mathcal{E}_N)(u_0)}_{H^r(\mathbb{T}^d)} \leq C B=:\Bar{B}$. Next, we make the rough estimate that,
\begin{equation}
    \norm{D^{(k,{\bm{\alpha}})}({\widehat{\mathcal{Q}}}_N-\mathcal{Q}_N)\circ \mathcal{E}_N){\widehat{\mathcal{G}}}(u_0)}_{L^2} \leq C N^d M^{s+k-1}\ln^k(M)\max_k\norm{\bm{\mathrm{e}}_k-\widehat{\bm{\mathrm{e}}}_k}_{C^r}. 
\end{equation}
Finally, using Lemma \ref{lem:wlog-faa-di-bruno} we find that
\begin{equation}
    \norm{D^{(k,{\bm{\alpha}})}({\widehat{\mathcal{Q}}}_N\circ \mathcal{E}_N\circ {\widehat{\mathcal{G}}}-\mathcal{G}_\theta)(u_0)}_{L^2}\leq \delta. 
\end{equation}
By setting $\eta = N^{\ell-r-d}$, $h=1/N$ and using that $M^{2k}\leq M^{k+s-1}$ and $C_{\varepsilon,\ell}^{\Bar{B}}\leq C_{\varepsilon,r}^{\Bar{B}}$ we find, 
\begin{equation}
    \norm{\mathcal{L}(\mathcal{G}-\mathcal{G}_\theta)}_{L^2} \leq C\ln^k(M)(\norm{u}_{C^{(s,\ell)}}M^{k-s}+M^{k+s-1}((\varepsilon+C^\varepsilon_{\mathrm{stab}}Z^{-r+d/p^*})N^{\ell}+C^{\Bar{B}}_{\varepsilon,r}N^{\ell-r})). 
\end{equation}
We conclude by using that $\ln^k(M)\leq CM^\rho$ for any $\rho>0$. 

\textbf{Step 3: size estimate.} It follows immediately that $\mathrm{depth}({\bm{\beta}})=\mathrm{depth}(\mathcal{U}^\varepsilon)$, $\mathrm{width}({\bm{\beta}}) = \mathcal{O}(M(Z^d+N^d\mathrm{width}(\mathcal{U}^\varepsilon)))$, 
$\mathrm{depth}({\bm{\tau}}) = 3$ and $\mathrm{width}({\bm{\tau}}) = \mathcal{O}(MN^d(N+\ln(N)))$.

