\label{lem:faa-di-bruno}
Let $\ell\in \mathbb{N}$, $f\in C^\ell(\mathbb{R},\mathbb{R})$, $h\in C^\ell(\mathbb{T}^d, \mathbb{R})$ and let $B_\ell$ denote the $\ell$-th Bell number. Then it holds that
\begin{equation}
     \abs{ f\circ h}_{C^\ell(\mathbb{R})} \leq \norm{f}_{C^\ell(\mathbb{R})}\left(B_\ell\norm{h}_{C^{\ell-1}(\mathbb{T}^d)}^\ell+ \abs{ h}_{C^\ell(\mathbb{T}^d)}\right).
\end{equation}

Let $\Pi$ be the set of all partitions of the set $\{1, \ldots, \ell\}$, let $\alpha\in \mathbb{N}_0^d$ such that $\norm{\alpha}_1=\ell$ and let $\iota:\mathbb{N}^\ell\to\mathbb{N}^d$ be a map such that $D^\alpha = \frac{\partial^\ell}{\prod_{j=1}^\ell x_{\iota(j)}}$. Then the Faà di Bruno formula can be reformulated as \cite{constantine1996multivariate}, 
\begin{equation}
\begin{split}
    D^\alpha f(h(x)) &= \sum_{\pi\in\Pi}f^{(\abs{\pi})}(h(x))\cdot \prod_{B\in\pi} \frac{\partial^{\abs{B}}h(x)}{\prod_{j\in B} \partial x_{\iota(j)}}\\
    &= \sum_{\substack{\pi\in\Pi,\\\abs{\pi}\geq 2}}f^{(\abs{\pi})}(h(x))\cdot \prod_{B\in\pi} \frac{\partial^{\abs{B}}h(x)}{\prod_{j\in B} \partial x_{\iota(j)}} + f'(h(x)) D^\alpha h(x). 
\end{split}
\end{equation}
Combining this formula with the definition of the Bell number as $B_\ell = \abs{\Pi}$, we find the following upper bound, 
\begin{equation}
\begin{split}
    \abs{ f\circ h}_{C^\ell(\mathbb{R})} &\leq \sum_{\pi\in\Pi}\norm{f}_{C^\ell(\mathbb{R})}\norm{h}_{C^{\ell-1}(\mathbb{R})}^\ell +  \norm{f}_{C^1(\mathbb{R})} \abs{ h}_{C^\ell(\mathbb{R})}\\
    &\leq \norm{f}_{C^\ell(\mathbb{R})}\left(B_\ell\norm{h}_{C^{\ell-1}(\mathbb{R})}^\ell+ \abs{ h}_{C^\ell(\mathbb{R})}\right).
\end{split}
\end{equation}

