$\theta\in\Theta$, satisfy for all 
$n\in\mathbb{N}_0$, 
$\theta\in\Theta$, $t\in[0,T]$, $x\in\mathbb{T}^d$ that 
\begin{equation}\label{eq:mlp}
\begin{split}
U_n^\theta(t,x) 
& = \frac{\1_\mathbb{N}(n)}{m^n} \br[\Bigg]{ \sum_{k=1}^{m^n} g\pr[\bigl]{x + W_{T-t}^{(\theta,0,-k)}} } \\
& \quad + \sum_{i=0}^{n-1} \frac{(T-t)}{m^{n-i}}\br[\Bigg]{ \sum_{k=1}^{m^{n-i}} \pr[]{ F(U_i^{(\theta,i,k)}) - \1_\mathbb{N}(i) F( U_{i-1}^{(\theta,-i,k)}) } \pr[]{ \EuScript{U}_t^{(\theta,i,k)}, x + W_{\EuScript{U}_t^{(\theta,i,k)}-t}^{(\theta,i,k)} } }.
\end{split}
\end{equation}

\begin{equation}\label{eq:mlp}
\begin{split}
U_n^\theta(t,x) 
& = \frac{\1_\mathbb{N}(n)}{m^n} \br[\Bigg]{ \sum_{k=1}^{m^n} g\pr[\bigl]{x + W_{T-t}^{(\theta,0,-k)}} } \\
& \quad + \sum_{i=0}^{n-1} \frac{(T-t)}{m^{n-i}}\br[\Bigg]{ \sum_{k=1}^{m^{n-i}} \pr[]{ F(U_i^{(\theta,i,k)}) - \1_\mathbb{N}(i) F( U_{i-1}^{(\theta,-i,k)}) } \pr[]{ \EuScript{U}_t^{(\theta,i,k)}, x + W_{\EuScript{U}_t^{(\theta,i,k)}-t}^{(\theta,i,k)} } }.
