\begin{equation}\label{eq:nn-mlp}
\begin{split}
\widehat{U}_n^\theta(t,x) 
& = \frac{\1_\mathbb{N}(n)}{m^n} \br[\Bigg]{ \sum_{k=1}^{m^n} (\mathcal{I}^{n-1}\circ\widehat{g})\pr[\bigl]{x + W_{T-t}^{(\theta,0,-k)}} } \\
& \quad + \sum_{i=0}^{n-1} \frac{(T-t)}{m^{n-i}}\br[\Bigg]{ \sum_{k=1}^{m^{n-i}} \pr[]{ (\mathcal{I}^{n-i-1}\circ\widehat{F})(\widehat{U}_i^{(\theta,i,k)}) - \1_\mathbb{N}(i) (\mathcal{I}^{n-i}\circ\widehat{F})( \widehat{U}_{i-1}^{(\theta,-i,k)}) } \pr[]{ \EuScript{U}_t^{(\theta,i,k)}, x + W_{\EuScript{U}_t^{(\theta,i,k)}-t}^{(\theta,i,k)} } }, 
