We define 
\begin{equation}\label{eq:omega}
    \omega : [0,T]\times \mathbb{N}^2\to \Omega: (t,n,m)\mapsto \overline{\omega}(t,n,m)
\end{equation}
and set for every $1\leq k\leq n$,
\begin{equation}\label{eq:def-nn}
    \widehat{U}_{k,\omega}^\theta(t,x) = \widehat{U}_k^\theta(\omega(t,n,m))(t,x)\quad \text{and} \quad U_{k,\omega}^\theta(t,x) = U_k^\theta(\omega(t,n,m))(t,x)
\end{equation}
for all $k\in\mathbb{N}_0$ and all $\theta\in\Theta$. We then define our approximation as $\widehat{U}_{n,\omega}^0(t,\cdot)$.




\textbf{Step 2: error estimate. }
We will quantify how well $\widehat{U}_{n,\omega}^0$ approximates $U_{n,\omega}^0$. Using the calculation that for $f_1,f_2\in  C^1(\mathbb{R})$ and $h_1, h_2\in L^2(\mu)$ it holds that
\begin{equation}
\begin{split}
\norm{f_1\circ h_1 - f_2\circ h_2}_{L^2(\mu)} &\leq \norm{f_1\circ h_1 - f_2\circ h_1}_{L^2(\mu)} + \norm{f_2\circ h_1 - f_2\circ h_2}_{L^2(\mu)}\\
&\leq \norm{f_1-f_2}_{C^0(\mathbb{R})} + \abs{f_2}_{Lip(\mathbb{R})}\norm{h_1-h_2}_{L^2(\mu)}, 
\end{split}
\end{equation}
and the fact that $2n\leq 2^n$ for $n\in\mathbb{N}$ we find that it holds for every $\theta\in\Theta$ that,
\begin{equation}\label{eq:uhat-un-calc}
\begin{split}
    &\norm{\widehat{U}_{n,\omega}^\theta(t,\cdot)-U^\theta_{n,\omega}(t,\cdot)}_{L^2(\mu)} \\ & \quad \leq \1_\mathbb{N}(n) \left(\norm{\widehat{g}-g}_{L^2(\mu)}+(n-1)\norm{\mathcal{I}-\mathrm{Id}}_{C^0}\right)
    + T \sum_{i=0}^{n-1} \norm{\mathcal{I}^{n-i-1}\circ\widehat{F}\circ \widehat{U}_{i,\omega}^{(\theta,i,k)}-F\circ U_{i,\omega}^{(\theta,i,k)}}_{L^2(\mu)} \\& \qquad + T \sum_{i=0}^{n-1}\1_\mathbb{N}(i) \norm{\mathcal{I}^{n-i}\circ\widehat{F}\circ \widehat{U}_{i-1,\omega}^{(\theta,-i,k)}-F\circ U_{i-1,\omega}^{(\theta,-i,k)}}_{L^2(\mu)} \\
    & \quad \leq \1_\mathbb{N}(n) \left[\norm{\widehat{g}-g}_{L^2(\mu)} + 2Tn\norm{\widehat{F}-F}_{C^0(\mathbb{R})}+ \left((n-1)+\frac{(n-1)n}{2}+\frac{(n+1)n}{2}\right)\norm{\mathcal{I}-\mathrm{Id}}_{C^0}\right]\\
    &\qquad + LT \sum_{i=0}^{n-1}\left(\norm{\widehat{U}_i^{(\theta,i,k)}- U_i^{(\theta,i,k)}}_{L^2(\mu)} + \1_\mathbb{N}(i)\norm{ \widehat{U}_{i-1}^{(\theta,-i,k)}- U_{i-1}^{(\theta,-i,k)}}_{L^2(\mu)} \right)\\
    & \quad \leq \1_\mathbb{N}(n)2^n \left[\norm{\widehat{g}-g}_{L^2(\mu)} + T\norm{\widehat{F}-F}_{C^0(\mathbb{R})}+ n\norm{\mathcal{I}-\mathrm{Id}}_{C^0}\right]\\
    &\qquad + \sum_{i=0}^{n-1} (\max\{1,LT\})^{n-i} \left(\norm{\widehat{U}_i^{(\theta,i,k)}- U_i^{(\theta,i,k)}}_{L^2(\mu)} + \1_\mathbb{N}(i)\norm{ \widehat{U}_{i-1}^{(\theta,-i,k)}- U_{i-1}^{(\theta,-i,k)}}_{L^2(\mu)} \right).
\end{split}, 
\end{equation}

Now let us set for every $k\in\mathbb{N}_0$, 
\begin{equation}
    x_k = \sup_{\theta\in\Theta} \norm{\widehat{U}_{k,\omega}^\theta(t,\cdot)-U^\theta_{k,\omega}(t,\cdot)}_{L^2(\mu)},
\end{equation}
and in addition we define $\alpha_0 = \norm{\widehat{g}-g}_{L^2(\mu)} +T\norm{\widehat{F}-F}_{C^0(\mathbb{R})}$, $\alpha_1 =  \norm{\mathcal{I}-\mathrm{Id}}_{C^0}$ and $\beta = 2+LT$.  
Taking the supremum over all $\theta\in\Theta$ in \eqref{eq:uhat-un-calc} gives us for all $k\in\mathbb{N}_0$ that,
\begin{equation}
\begin{split}
    x_k 
    &\leq \1_\mathbb{N}(k)(\alpha_0+\alpha_1k)\beta^k + \sum_{i=0}^{k-1} \beta^{k-i} (x_{i}+x_{\max\{i-1,0\}}). 
\end{split}
\end{equation}
Therefore, we can use Lemma \ref{lem:recursion1} with $\gamma\leftarrow 0$ then gives us that for all $k\in\mathbb{N}_0$ it holds that,
\begin{equation}\label{eq:mlp-to-nn}
\begin{split}
    &\sup_{\theta\in\Theta} \norm{\widehat{U}_{k,\omega}^\theta(t,\cdot)-U^\theta_{k,\omega}(t,\cdot)}_{L^2(\mu)}\\ &\qquad\leq \1_\mathbb{N}(k) \frac{(1+\sqrt{2})^k}{2} \left(\norm{\widehat{g}-g}_{L^2(\mu)}+T\norm{\widehat{F}-F}_{C^0(\mathbb{R})}+ \norm{\mathcal{I}-\mathrm{Id}}_{C^0}\right)(2+LT)^k.
\end{split}
\end{equation}
Next we define
\begin{equation}\label{eq:C1-C2}
    C_1 = (T+1)(1+\mathcal{L} \exp(LT)), \qquad C_2 = 5+3LT.
\end{equation}
Combining \eqref{eq:true-to-mlp} with \eqref{eq:mlp-to-nn} then gives us that, 
\begin{equation}\label{eq:nn-error-bound}
\begin{split}
     &\norm{\widehat{U}^0_{n,\omega}(t,\cdot)-u(t,\cdot)}_{L^2(\mu)} \\
     &\quad \leq \norm{\widehat{U}^0_{n,\omega}(t,\cdot)-U^0_{n,\omega}(t,\cdot)}_{L^2(\mu)}+\norm{U^0_{n,\omega}(t,\cdot)-u(t,\cdot)}_{L^2(\mu)}\\

     &\quad \leq C_1 C_2^n \left( \norm{\widehat{g}-g}_{L^2(\mu)}+\norm{\widehat{F}-F}_{C^0(\mathbb{R})} + \norm{\mathcal{I}-\mathrm{Id}}_{C^0}+ m^{-n/2}\exp(m/2)\right). 
\end{split}
\end{equation}
For an arbitrary $\sigma>0$, we choose
\begin{equation}\label{eq:mn-choice}
    m = C_2^{2(1+1/\sigma)}, \qquad n = \sigma\log_{C_2} (4C_1\exp(m/2)/\varepsilon)
\end{equation}
and if we choose $\widehat{g}=\widehat{g}_\delta$ and $\widehat{F} = \widehat{F}_\delta$ such that,
\begin{equation}\label{eq:delta-eta}
\begin{split}
    \norm{\widehat{g}-g}_{L^2(\mu)} \leq \delta = \frac{\varepsilon}{4C_1C_2^n} = \frac{\varepsilon^{1+\sigma}}{(4C_1)^{1+\sigma}\exp(\sigma m/2)}, 
\end{split}
\end{equation}
then we obtain that
\begin{equation}
    \norm{\widehat{U}^0_{n,\omega}(t,\cdot)-u(t,\cdot)}_{L^2(\mu)} \leq \varepsilon. 
\end{equation}

\textbf{Step 3: size estimate. }
We now provide estimates on the size of the network constructed in Step 1. 
First of all, it is straightforward to see that the depth of the network can be bounded by
\begin{equation}\label{eq:L-nn}
     \mathcal{L}_\varepsilon(\widehat{U}^0_{n,\omega}) \leq \mathcal{L}_\delta(\widehat{g})+(n-1)\mathcal{L}_\delta(\widehat{F}) \leq \mathcal{L}_{\delta}(\widehat{g})+\log_{C_2} (3C_1\exp(m/2)/\varepsilon)\mathcal{L}_\delta(\widehat{F}). 
\end{equation}
Next we prove an estimate on the number of needed neurons. For notation, we write $\mathcal{M}_{n} = \mathcal{M}_\varepsilon(\widehat{U}^0_{n,\omega})$. We find that for all $0\leq k\leq n$,
\begin{equation}\label{eq:mlp-cost-recursion}
\begin{split}
    \mathcal{M}_k &\leq \1_\mathbb{N}(k) m^k (\mathcal{M}_\delta(\widehat{g})+(k-1)\mathcal{M}_\delta(\mathcal{I})) \\
    &\quad+ \sum_{i=0}^{k-1} m^{k-i} (2\mathcal{M}_\delta(\widehat{F}) + (2k-2i-1)\mathcal{M}_\delta(\mathcal{I})+ \mathcal{M}_i + \mathcal{M}_{\max\{i-1,0\}})\\
    &\leq \1_\mathbb{N}(k)(\mathcal{M}_\delta(\widehat{g})+ \mathcal{M}_\delta(\widehat{F})+k\mathcal{M}_\delta(\mathcal{I}))(2m)^k+ \sum_{i=0}^{k-1} m^{k-i} (\mathcal{M}_i + \mathcal{M}_{\max\{i-1,0\}}).
\end{split}
\end{equation}
Applying Lemma \ref{lem:recursion1} to \eqref{eq:mlp-cost-recursion} (i.e. $\alpha_0\leftarrow \mathcal{M}_\delta(\widehat{g})+\mathcal{M}_\delta(\widehat{F})$, $\alpha_1\leftarrow \mathcal{M}_\delta(\mathcal{I})$ and $\beta\leftarrow 2m$) then gives us that
\begin{equation}\label{eq:M-nn}
    \mathcal{M}_n \leq \frac{1}{2}(\mathcal{M}_\delta(\widehat{g})+ \mathcal{M}_\delta(\widehat{F})+ \mathcal{M}_\delta(\mathcal{I})) (1+ \sqrt{2} )^n (2m)^n. 
\end{equation}
Observing that $2+2\sqrt{2} \leq C_2$ and recalling that $m=C_2^{2(1+1/\sigma)}$ we find that
\begin{equation}
\begin{split}
    \mathcal{M}_n &\leq \frac{1}{2}(\mathcal{M}_\delta(\widehat{g})+ \mathcal{M}_\delta(\widehat{F})+ \mathcal{M}_\delta(\mathcal{I})) C_2^{(3\sigma+2)n/\sigma}\\
    &= \frac{1}{2}(\mathcal{M}_\delta(\widehat{g})+ \mathcal{M}_\delta(\widehat{F})+ \mathcal{M}_\delta(\mathcal{I})) \left(\frac{4C_1\exp(m/2)}{\varepsilon}\right)^{2+3\sigma}. 
\end{split}
\end{equation}
For the width, we make the estimate $\mathrm{width}_\varepsilon(\widehat{U}^0_{n,\omega}) \leq \mathcal{M}_n$.

\begin{equation}
\begin{split}
\norm{f_1\circ h_1 - f_2\circ h_2}_{L^2(\mu)} &\leq \norm{f_1\circ h_1 - f_2\circ h_1}_{L^2(\mu)} + \norm{f_2\circ h_1 - f_2\circ h_2}_{L^2(\mu)}\\
&\leq \norm{f_1-f_2}_{C^0(\mathbb{R})} + \abs{f_2}_{Lip(\mathbb{R})}\norm{h_1-h_2}_{L^2(\mu)}, 
\end{split}
\end{equation}

\label{lem:space-der-nn}
Assume Setting \ref{set:pinn}. Under the assumption that,
\begin{equation}
\max_{1\leq j\leq k}\norm{\mathcal{I}^j}_{C^k([-\mathcal{L}-1, \mathcal{L}+1])}\leq 2, 
\end{equation}
where $\mathcal{I}^j$ denotes $j$ compositions of $\mathcal{I}$, it holds for all $\ell, k\in\mathbb{N}_0$ that,
\begin{equation}\label{eq:pinn-x-claim}
\begin{split}
     &\sup_{\theta\in\Theta} \norm{ \widehat{U}^\theta_{k,\omega}}_{C^{(0,\ell)}([0,T]\times\mathbb{T}^d)} \leq C_{k,\ell} := \left[\norm{\widehat{g}}_{C^\ell(\mathbb{T}^d)}+2B_\ell (1+\sqrt{2})^k (1+2B_\ell T\norm{\widehat{F}}_{C^\ell(\mathbb{R})}^\ell)^k\right]^{2(\ell+1)!},
\end{split}
\end{equation}
and where $B_\ell$ denote the $\ell$-th Bell number i.e., the number of possible partitions of a set with $\ell$ elements.

We prove the claim by induction on $\ell$. 

\textit{Base case.} From Definition \ref{def:MLP}, we find that for $\ell = 0$ and all $k\in\mathbb{N}_0$ it holds that
\begin{equation}\label{eq:base-case}
    \sup_{\theta\in\Theta} \norm{\widehat{U}^\theta_{k,\omega}}_{C^{0}([0,T]\times\mathbb{T}^d)} \leq \norm{\widehat{g}}_{C^{0}(\mathbb{T}^d)} + 2T\norm{\widehat{F}}_{C^{0}(\mathbb{R})}k. 
\end{equation}
Claim \eqref{eq:pinn-x-claim} follows immediately for $\ell=0$. 

\textit{Induction step.} We assume that claim \eqref{eq:pinn-x-claim} holds true for all $0\leq \ell^*\leq \ell-1$ and $k\in\mathbb{N}_0$. From this assumption, we will deduce that \eqref{eq:pinn-x-claim} holds true for $\ell$ and all $k\in\mathbb{N}_0$. We first observe that it follows from Lemma \ref{lem:faa-di-bruno}, the induction hypothesis and the fact that $(C_{k,\ell})_{\ell\geq0}$ is non-decreasing for any $k$, that for all $\theta\in\Theta$ and $0\leq i,j\leq k$ it holds that,
\begin{equation}\label{eq:composition-chain-rule}
\begin{split}
    \abs{ (\mathcal{I}^j\circ\widehat{F})(\widehat{U}^{\theta}_{i,\omega})}_{C^\ell([0,T]\times\mathbb{T}^d)} \leq \norm{\mathcal{I}^j\circ\widehat{F}}_{C^{\ell}(\mathbb{R})}\left(B_\ell C_{k,\ell-1}^\ell+ \abs{ \widehat{U}^{\theta}_{i,\omega}}_{C^{(0,\ell)}([0,T]\times\mathbb{T}^d)}\right),
\end{split}
\end{equation}
and where (again using Lemma \ref{lem:faa-di-bruno}) it holds that $\norm{\mathcal{I}^j\circ\widehat{F}}_{C^{\ell}(\mathbb{R})} \leq 2B_\ell \norm{\widehat{F}}_{C^{\ell}}^\ell$. 

Using this estimate and the fact that $(C_{k,\ell})_{k\geq0}$ is non-decreasing for any $\ell$, we can make the following calculation for every $k\in\mathbb{N}_0$,
\begin{equation}
    \begin{split}
        &\sup_{\theta\in\Theta} \abs{ \widehat{U}^\theta_{k,\omega}}_{C^{(0,\ell)}([0,T]\times\mathbb{T}^d)} \\&\leq \1_{\mathbb{N}}(k)\abs{\widehat{g}}_{C^\ell(\mathbb{T}^d)} + T \sum_{i=0}^{k-1} \sup_{\theta\in\Theta}\abs{ (\mathcal{I}^{k-i-1}\circ\widehat{F})(\widehat{U}^{\theta}_{i,\omega})}_{C^{(0,\ell)}(([0,T]\times\mathbb{T}^d))}\\&\quad +T \sum_{i=0}^{k-1}\1_{\mathbb{N}}(i)\sup_{\theta\in\Theta}\abs{ (\mathcal{I}^{k-i}\circ\widehat{F})(\widehat{U}^{\theta}_{i-1,\omega})}_{C^{(0,\ell)}(([0,T]\times\mathbb{T}^d))}\\
        &\leq \1_{\mathbb{N}}(k)\abs{\widehat{g}}_{C^\ell(\mathbb{T}^d)} + 2B_\ell T\norm{\widehat{F}}_{C^\ell(\mathbb{R})}^\ell \sum_{i=0}^{k-1} \left(B_\ell C_{k,\ell-1}^\ell+\sup_{\theta\in\Theta}\abs{ \widehat{U}^{\theta}_{i,\omega}}_{C^{(0,\ell)}(([0,T]\times\mathbb{T}^d))}\right)\\
        &\quad +2B_\ell T\norm{\widehat{F}}_{C^\ell(\mathbb{R})}^\ell \sum_{i=0}^{k-1} \1_{\mathbb{N}}(i)\left(B_\ell C_{k,\ell-1}^\ell+\sup_{\theta\in\Theta}\abs{ \widehat{U}^{\theta}_{i-1,\omega}}_{C^{(0,\ell)}(([0,T]\times\mathbb{T}^d))}\right)\\
        &\leq \1_{\mathbb{N}}(k)(\abs{\widehat{g}}_{C^\ell(\mathbb{T}^d)} + 2B_\ell T \norm{\widehat{F}}_{C^\ell(\mathbb{R})}^\ell C_{k,\ell-1}^\ell k)\\
        &\quad + \sum_{i=0}^{k-1}2B_\ell T\norm{\widehat{F}}_{C^\ell(\mathbb{R})}^\ell\left(\sup_{\theta\in\Theta}\abs{ \widehat{U}^{\theta}_{i,\omega}}_{C^{(0,\ell)}(([0,T]\times\mathbb{T}^d))} + \1_{\mathbb{N}}(i)\sup_{\theta\in\Theta}\abs{ \widehat{U}^{\theta}_{i-1,\omega}}_{C^{(0,\ell)}(([0,T]\times\mathbb{T}^d))}\right)
    \end{split}
\end{equation}

Application of Lemma \ref{lem:recursion1} with $\alpha_0\leftarrow \abs{\widehat{g}}_{C^\ell(\mathbb{T}^d)}$, $\alpha_1 \leftarrow  2B_\ell C_{k,\ell-1}^\ell $, $\beta \leftarrow (1+2B_\ell T\norm{\widehat{F}}_{C^\ell(\mathbb{R})}^\ell)$ and $\gamma \leftarrow 0$ gives us
\begin{equation}
\begin{split}
    \sup_{\theta\in\Theta} \norm{ \widehat{U}^\theta_{k,\omega}}_{C^{0}([0,T]\times\mathbb{T}^d)} &\leq \frac{\abs{\widehat{g}}_{C^\ell(\mathbb{T}^d)} + 2B_\ell C_{k,\ell-1}^\ell}{2}(1+\sqrt{2})^k (1+2B_\ell T\norm{\widehat{F}}_{C^\ell(\mathbb{R})}^\ell)^k \\
    &\leq \left[\abs{\widehat{g}}_{C^\ell(\mathbb{T}^d)}+2B_\ell (1+\sqrt{2})^k (1+2B_\ell T\norm{\widehat{F}}_{C^\ell(\mathbb{R})}^\ell)^k\right]C_{k,\ell-1}^\ell. 
\end{split}
\end{equation}
Filling in the definition of $C_{k,\ell-1}$ indeed gives us the formula as stated in \eqref{eq:pinn-x-claim}, thereby concluding the proof of the claim.

\label{lem:ass-check-ac}
Let $F$ be a polynomial. For every $\sigma, \varepsilon>0$ there is an operator $\mathcal{U}^\varepsilon$ as in Assumption \ref{ass:nn} such that for every $t\in [0,T]$,
\begin{equation}
    \norm{\mathcal{U}^\varepsilon(u_0,t)-\mathcal{G}(v)(u_0,t)}_{L^2(\mathbb{T}^d)} \leq \varepsilon, \qquad C_{\varepsilon,\ell}^B \leq C(B\varepsilon^{-\sigma})^{2(l+1)!}, \qquad C^\varepsilon_{\mathrm{stab}} \leq C\varepsilon^{-\sigma}. 
\end{equation}
Moreover it holds that $\mathrm{depth}(\mathcal{U}^\varepsilon(u_0,t)) \leq \mathrm{depth}({\widehat{u}}_0)+C\ln(\varepsilon^{-1})$, $\mathrm{width}(\mathcal{U}^\varepsilon(u_0,t)) \leq \mathrm{width}({\widehat{u}}_0)\varepsilon^{-2-\sigma}$ and $\mathrm{size}(\mathcal{U}^\varepsilon(u_0,t)) \leq \mathrm{size}({\widehat{u}}_0)\varepsilon^{-2-\sigma}$.

\label{lem:rec-fourier}
Let $s, d, p\in \mathbb{N}$. For any $\varepsilon>0$, there exists a trunk net ${\bm{\tau}}: \mathbb{R}^d \to \mathbb{R}^p$ with 2 hidden layers of width $\mathcal{O}(p^{\frac{d+1}{d}}+ps\ln(ps\varepsilon^{-1}))$ and such that 
\begin{align} \label{eq:Fourier-NN}
p^{3/2} \max_{j=1,\dots, p} \Vert {{\tau}}_j - \bm{\mathrm{e}}_j \Vert_{C^s([0,2\pi]^d)}
\le \varepsilon,
\end{align}
where $\bm{\mathrm{e}}_1,\dots, \bm{\mathrm{e}}_p$ denote the first $p$ elements of the Fourier basis, as in \textbf{SM} \ref{app:Fourier}.

We note that each element in the (real) trigonometric basis $\bm{\mathrm{e}}_1,\dots, \bm{\mathrm{e}}_p$ can be expressed in the form 
\begin{equation}
\bm{\mathrm{e}}_j({x}) 
=
\cos(\kappa\cdot {x}),
\quad
\text{or}
\quad
\bm{\mathrm{e}}_j({x}) = \sin(\kappa\cdot {x}),
\end{equation}
for $\kappa = \kappa(j)\in \mathbb{Z}^d$ with $|\kappa|_\infty \le N$, where $N$ is chosen as the smallest natural number such that $p \le (2N+1)^d$. We focus only focus on the first form, as the proof for the second form is entirely similar. Define $f:[0,2\pi]^d\to\mathbb{R}:x\mapsto 

\kappa\cdot x$ and $g:[-2\pi dN, 2\pi dN]\to\mathbb{R}:x\mapsto \cos(x)$. As $f([0,2\pi]^d) \subset [-2\pi dN, 2\pi dN]$, the composition $g\circ f$ is well-defined and one can see that it coincides with a trigonometric basis function $\bm{\mathrm{e}}_j$. 
Moreover, the linear map $f$ is a trivial neural network without hidden layers. Approximating $\bm{\mathrm{e}}_j$ by a neural network $\tau_j$ therefore boils down to approximating $g$ by a suitable neural network. 

From \cite[Theorem 5.1]{deryck2021approximation} it follows that the function $g$ there exists an independent constant $R>0$ such that for large enough $t\in\mathbb{N}$ there is a tanh neural network $\widehat{g}_t$ with two hidden layers and $\mathcal{O}(t+N)$ neurons such that
\begin{equation}
    \norm{g-\widehat{g}_t}_{C^s([-2\pi dN, 2\pi dN])} \leq 4 (8(s+1)^3R)^{s} \exp(t-s). 
\end{equation}
This can be proven from \cite[eq. (74)]{deryck2021approximation} by setting $\delta\leftarrow\frac{1}{3}$, $k\leftarrow s$, $s\leftarrow t$, $N\leftarrow 2$ and using $\norm{g}_{C^s}=1$ and Stirling's approximation to obtain
\begin{equation}
    \frac{1}{(t-s)!}\left(\frac{3}{2\cdot 2}\right)^{t-s} \leq \frac{1}{\sqrt{2\pi(t-s)}} \left(\frac{e}{t-s}\right)^{t-s} \leq \exp(s-t) \quad \text{for } t>s+e^2. 
\end{equation}
Setting $t = \mathcal{O}(\ln(\delta^{-1})+s\ln(s))$ then gives a neural network $\widehat{g}_t$ with $\norm{g-\widehat{g}_t}_{C^s}<\eta$. Next, it follows from \cite[Lemma A.7]{deryck2021approximation} that
\begin{align}
\begin{split}
    \norm{g\circ f-\widehat{g}_t\circ f}_{C^s([0,2\pi]^d)} &\leq 16(e^2s^4d^2)^s \norm{g-\widehat{g}_t}_{C^s([-2\pi dN, 2\pi dN])} \norm{f}_{C^s([0,2\pi]^d)}^s\\
    &\leq 16(e^2s^4d^2)^s \eta (2\pi dN)^s. 
\end{split}
\end{align}
From this follows that we can obtain the desired accuracy \eqref{eq:Fourier-NN} if we set $\tau_j = \widehat{g}_{t(\eta)}\circ f$ with
\begin{equation}
    \eta = \frac{\varepsilon p^{-3/2}}{16(2\pi Nd^3e^2s^4)^{s}},
\end{equation}
which amounts to $t = \mathcal{O}(s\ln(sN\varepsilon^{-1}))$. As a consequence, the tanh neural network $\tau_j$ has two hidden layers with $\mathcal{O}(s\ln(sN\varepsilon^{-1})+N)$ neurons and therefore, by recalling that $p\sim N^d$, the combined network $\bm{\tau}$ has two hidden layers with
\begin{equation}
    \mathcal{O}(p(s\ln(sN\varepsilon^{-1})+N)) = \mathcal{O}(ps\ln(ps\varepsilon^{-1})+p^{\frac{d+1}{d}})
\end{equation}
neurons.

Consider the setting of Theorem \ref{thm:linear-pido}. Using \cite[Theorem D.3]{LMK1}, the reasoning as in \cite[Example D.4]{LMK1} and Lemma \ref{lem:rec-fourier} we find that there exists a constant $C = C(d,\ell)>0$, such that for any $m, p, s \in \mathbb{N}$ there exists a DeepONet with trunk net ${\bm{\tau}}$ and branch net ${\bm{\beta}}$, such that 
\begin{gather}
\mathrm{size}({\bm{\tau}}) \le C(p^{\frac{d+1}{d}}+ps\ln(ps\varepsilon^{-1})),
\quad
\mathrm{depth}({\bm{\tau}}) = 3,
\end{gather}
and where 
\begin{gather}
\mathrm{size}({\bm{\beta}}) \le p, 
\quad
\mathrm{depth}({\bm{\beta}}) \le 1,
\end{gather}
and such that the DeepONet approximation error \eqref{eq:approxerr} is bounded by 
\begin{equation}
\norm{\mathcal{G}(v)-\mathcal{G}_\theta(v)}_{L^2(\mu\times\lambda)}
\le \varepsilon + 
C\exp\left(-c\, p^{1/d}\right) + 
C \exp\left(-\frac{c\,m^{1/d}}{\log(m)^{1/d}}\right). 
\end{equation}
Moreover, it holds that
\begin{equation}
     \abs{\mathcal{N}(u)(\cdot)}_{C^s} \leq C p^{s/d}, 
\end{equation}
since in this case ${\bm{\tau}}$ approximates the Fourier basis (\textbf{SM} \ref{app:Fourier}). From \eqref{eq:bound-fourier-basis}, one can then deduce the estimate on the $C^s$-norm of the DeepONet. This proves that \eqref{eq:growth} in Theorem \ref{thm:deeponet-to-pido} holds with $\sigma(s)=s/d$. This concludes the proof.

