 \label{thm:be-expansion}
Let $V$ be a Banach space and let $\mathcal{J}$ be a  countable index set. Let $\mathcal{F}: [-1,1]^\mathcal{J} \to V$ be a $(\bm{b},\varepsilon,\kappa)$-holomorphic map for some $\bm{b}\in \ell^q(\mathbb{N})$ and $q\in (0,1)$, and an enumeration $\kappa: \mathbb{N} \to \mathcal{J}$. Then there exists a constant $C>0$, such that for every $N\in \mathbb{N}$, there exists an index set 
\begin{equation}
\Lambda_N
\subset
\set{
\bm{\nu} = (\nu_1,\nu_2,\dots) \in \textstyle{\prod}_{j\in \mathcal{J}} \mathbb{N}_0
\:\vert\:
\nu_j\ne 0 \; \text{for finitely many $j\in \mathcal{J}$}
},    
\end{equation}
with $|\Lambda_N|=N$, a finite set of coefficients $\{c_{\bm{\nu}}\}_{\bm{\nu}\in \Lambda_N} \subset V$, and a tanh network $\Psi: \mathbb{R}^N \to \mathbb{R}^{\Lambda_N}$, $y\mapsto \{\Psi_{\bm{\nu}}(y)\}_{\bm{\nu}\in \Lambda_N}$ with
\begin{gather}
\mathrm{size}(\Psi) \le C(1+N\log(N) ), 
\quad
\mathrm{depth}(\Psi) \le C(1+\log\log(N)),
\end{gather}
and such that
\begin{align} \label{eq:be-expansion}
\sup_{\bm{y}\in [-1,1]^\mathcal{J}} 
\left\Vert
\mathcal{F}(\bm{y}) - \sum_{\bm{\nu}\in \Lambda_N} c_{\bm{\nu}} \Psi_{\bm{\nu}}(y_{\kappa(1)},\dots, y_{\kappa(N)})
\right\Vert_{V} 
\le C N^{1-1/q}.
\end{align}

 \label{cor:holomorphic-NN}
Let $V$ be a Banach space. Let $\mathcal{F}: [-1,1]^\mathcal{J} \to V$ be a $(\bm{b},\varepsilon,\kappa)$-holomorphic map for some $\bm{b}\in \ell^q(\mathbb{N})$ and $q\in (0,1)$, where $\kappa: \mathbb{N}\to \mathcal{J}$ is an enumeration of $\mathcal{J}$. In particular, it is assumed that $\{b_{j}\}_{j\in \mathbb{N}}$ is a monotonically decreasing sequence. If $\mathcal{P}: V \to \mathbb{R}^p$ is a continuous linear mapping, then there exists a constant $C>0$, such that for every $m\in \mathbb{N}$, there exists a tanh network $\Psi: \mathbb{R}^m \to \mathbb{R}^p$, with
\begin{gather}
\mathrm{size}(\Psi) \le C(1+pm\log(m) ), 
\quad
\mathrm{depth}(\Psi) \le C(1+ \log\log(m)),
\end{gather}
and such that
\begin{equation}
\sup_{\bm{y}\in [-1,1]^\mathcal{J}} \Vert \mathcal{P} \circ \mathcal{F}(\bm{y}) - \Psi(y_{\kappa(1)},\dots, y_{\kappa(m)})\Vert_{\ell^2(\mathbb{R}^p)} \le C \Vert \mathcal{P} \Vert \,  m^{-s}, 
\end{equation}
where $s := q^{-1} - 1 > 0$ and $\Vert \mathcal{P} \Vert = \Vert \mathcal{P} \Vert_{V\to \ell^2}$ denotes the operator norm.

